1	import { useState, useEffect, useMemo } from "react";
2	import {
3	  useListAssets, useCreateAsset, useUpdateAsset, useDeleteAsset, useAiEnhanceAsset,
4	  useGetProject, useUpdateProject, getListAssetsQueryKey, getGetProjectQueryKey,
5	  useListEntities, useCreateEntity, useUpdateEntity, useDeleteEntity,
6	  useAiGenerateEntities, useAiEnhanceEntity,
7	  useListEntityProperties, useCreateEntityProperty, useUpdateEntityProperty, useDeleteEntityProperty,
8	  useListRules,
9	  useListEntityRules, useLinkEntityRule, useUnlinkEntityRule, getListEntityRulesQueryKey,
10	  getListEntitiesQueryKey, getListEntityPropertiesQueryKey,
11	  type Asset, type AssetEnhanceSuggestion, type Entity, type EntityProperty,
12	} from "@workspace/api-client-react";
13	import { useQueryClient } from "@tanstack/react-query";
14	import {
15	  Plus, Trash2, ImageIcon, Edit2, Sparkles, Download, Loader2, Wand2, Save, BookOpen,
16	  Layers, Square, Circle, Dice5, User, Map as MapIcon, Package, Tag, Check, X, RefreshCw,
17	  ChevronDown, ChevronRight, Settings, Pencil, Copy, FileText, Activity, Eye,
18	} from "lucide-react";
19	import { Button } from "@/components/ui/button";
20	import { Card, CardContent } from "@/components/ui/card";
21	import { Input } from "@/components/ui/input";
22	import { Textarea } from "@/components/ui/textarea";
23	import { Label } from "@/components/ui/label";
24	import {
25	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
26	  SelectGroup, SelectLabel,
27	} from "@/components/ui/select";
28	import { Skeleton } from "@/components/ui/skeleton";
29	import { Badge } from "@/components/ui/badge";
30	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
31	import { useToast } from "@/hooks/use-toast";
32	
33	// ── Component type constants ──────────────────────────────────────────────────
34	
35	const PHYSICAL_TYPES = ["Card", "Deck", "Token", "Die", "Tile", "Meeple", "Board"] as const;
36	const WORLD_TYPES    = ["Location", "Faction", "Event", "Resource", "Ability"] as const;
37	const ALL_COMPONENT_TYPES = [...PHYSICAL_TYPES, ...WORLD_TYPES] as const;
38	type ComponentType = typeof ALL_COMPONENT_TYPES[number];
39	
40	const COMPONENT_META: Record<ComponentType, { icon: string; color: string; bg: string; badge: string; desc: string }> = {
41	  Card:     { icon: "🃏", color: "text-violet-400",  bg: "bg-violet-500/5",  badge: "bg-violet-500/20 text-violet-400 border-violet-500/30",  desc: "Action, item, spell, event, treasure cards" },
42	  Deck:     { icon: "📦", color: "text-indigo-400",  bg: "bg-indigo-500/5",  badge: "bg-indigo-500/20 text-indigo-400 border-indigo-500/30",  desc: "Collection of cards (container)" },
43	  Token:    { icon: "🪙", color: "text-amber-400",   bg: "bg-amber-500/5",   badge: "bg-amber-500/20 text-amber-400 border-amber-500/30",     desc: "Resource, currency, health, status markers" },
44	  Die:      { icon: "🎲", color: "text-red-400",     bg: "bg-red-500/5",     badge: "bg-red-500/20 text-red-400 border-red-500/30",           desc: "Custom die type or face set" },
45	  Tile:     { icon: "🗺️", color: "text-emerald-400", bg: "bg-emerald-500/5", badge: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30", desc: "Map, dungeon, terrain tiles" },
46	  Meeple:   { icon: "🧩", color: "text-blue-400",    bg: "bg-blue-500/5",    badge: "bg-blue-500/20 text-blue-400 border-blue-500/30",        desc: "Pawn, figure, standee, miniature" },
47	  Board:    { icon: "📋", color: "text-slate-400",   bg: "bg-slate-500/5",   badge: "bg-slate-500/20 text-slate-400 border-slate-500/30",     desc: "Game board, player mat, reference sheet" },
48	  Location: { icon: "📍", color: "text-cyan-400",    bg: "bg-cyan-500/5",    badge: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",        desc: "City, dungeon, region, landmark" },
49	  Faction:  { icon: "⚔️", color: "text-purple-400",  bg: "bg-purple-500/5",  badge: "bg-purple-500/20 text-purple-400 border-purple-500/30",  desc: "Guild, tribe, nation, team" },
50	  Event:    { icon: "⚡", color: "text-orange-400",  bg: "bg-orange-500/5",  badge: "bg-orange-500/20 text-orange-400 border-orange-500/30",  desc: "Random event, scenario, story beat" },
51	  Resource: { icon: "💎", color: "text-teal-400",    bg: "bg-teal-500/5",    badge: "bg-teal-500/20 text-teal-400 border-teal-500/30",        desc: "Material, food, energy, mana" },
52	  Ability:  { icon: "✨", color: "text-pink-400",    bg: "bg-pink-500/5",    badge: "bg-pink-500/20 text-pink-400 border-pink-500/30",        desc: "Passive, active, triggered, ultimate" },
53	};
54	
55	const STATUS_OPTIONS = [
56	  { value: "draft",     label: "Draft",      color: "bg-slate-500/20 text-slate-400 border-slate-500/30" },
57	  { value: "needs-art", label: "Needs Art",  color: "bg-amber-500/20 text-amber-400 border-amber-500/30" },
58	  { value: "ready",     label: "Ready",      color: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30" },
59	  { value: "approved",  label: "Approved",   color: "bg-blue-500/20 text-blue-400 border-blue-500/30" },
60	] as const;
61	
62	function getStatusMeta(status: string) {
63	  return STATUS_OPTIONS.find((s) => s.value === status) ?? STATUS_OPTIONS[0];
64	}
65	
66	const COMPONENT_SUBTYPES: Record<ComponentType, string[]> = {
67	  Card:     ["Action", "Item", "Spell", "Event", "Quest", "Encounter", "Treasure", "Attack", "Defense"],
68	  Deck:     ["Item Deck", "Event Deck", "Encounter Deck", "Spell Deck", "Quest Deck", "Custom"],
69	  Token:    ["Resource", "Currency", "Health", "Status", "Marker", "Victory Point", "Damage"],
