106	        method: "POST",
107	        headers: { "Content-Type": "application/json" },
108	        credentials: "include",
109	        body: JSON.stringify({ prompt, count: 1 }),
110	      });
111	      if (!res.ok) throw new Error("ingest failed");
112	      closeIngest();
113	      refresh();
114	      toast({ title: "Ingested", description: "AI summarized and added the source." });
115	    } catch { toast({ title: "Ingest failed", variant: "destructive" }); }
116	    finally { setIngesting(false); }
117	  };
118	
119	  return (
120	    <div className="space-y-6 max-w-6xl">
121	      <div className="flex items-end justify-between gap-4 flex-wrap">
122	        <div>
123	          <h2 className="text-2xl font-bold flex items-center gap-2"><BookOpen className="h-6 w-6 text-primary" /> Research</h2>
124	          <p className="text-muted-foreground text-sm mt-1">Capture inspirations, references, and design notes.</p>
125	        </div>
126	        <div className="flex gap-2">
127	          {!showIngest && !isFormOpen && (
