129	          )}
130	          {!isFormOpen && !showIngest && (
131	            <Button onClick={openCreate} className="gap-2" data-testid="add-research-button"><Plus className="h-4 w-4" /> Add Source</Button>
132	          )}
133	        </div>
134	      </div>
135	
136	      {isFormOpen && (
137	        <Card className="bg-card border-primary/40" data-testid="research-form-panel">
138	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
139	            <CardTitle className="text-base">{editing ? "Edit research source" : "Add research source"}</CardTitle>
140	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForm}><X className="h-4 w-4" /></Button>
141	          </CardHeader>
142	          <CardContent>
143	            <form onSubmit={submit} className="space-y-4">
144	              <div className="space-y-2"><Label>Title *</Label><Input value={form.title} onChange={e => setForm({...form, title: e.target.value})} required autoFocus /></div>
145	              <div className="space-y-2"><Label>Source URL or citation</Label><Input value={form.source} onChange={e => setForm({...form, source: e.target.value})} placeholder="https://..." /></div>
146	              <div className="space-y-2"><Label>Notes</Label><Textarea rows={5} value={form.content} onChange={e => setForm({...form, content: e.target.value})} /></div>
147	              <div className="space-y-2"><Label>Tags (comma-separated)</Label><Input value={form.tags} onChange={e => setForm({...form, tags: e.target.value})} placeholder="combat, economy" /></div>
148	              <div className="flex justify-end gap-2 pt-2">
149	                <Button type="button" variant="outline" onClick={closeForm}>Cancel</Button>
150	                <Button type="submit">{editing ? "Save" : "Add"}</Button>
151	              </div>
152	            </form>
153	          </CardContent>
154	        </Card>
155	      )}
156	
157	      {showIngest && (
158	        <Card className="bg-card border-primary/40" data-testid="research-ingest-panel">
159	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
160	            <div>
161	              <CardTitle className="text-base">AI Ingest</CardTitle>
162	              <p className="text-xs text-muted-foreground mt-1">Paste a URL or text and let AI summarize it into a research item.</p>
163	            </div>
164	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeIngest}><X className="h-4 w-4" /></Button>
165	          </CardHeader>
166	          <CardContent className="space-y-4">
167	            <div className="space-y-2"><Label>URL</Label><Input value={ingestUrl} onChange={e => setIngestUrl(e.target.value)} placeholder="https://..." autoFocus /></div>
168	            <div className="text-center text-xs text-muted-foreground">— or —</div>
169	            <div className="space-y-2"><Label>Paste text</Label><Textarea rows={6} value={ingestText} onChange={e => setIngestText(e.target.value)} /></div>
170	            <div className="flex justify-end gap-2 pt-2">
171	              <Button variant="outline" onClick={closeIngest}>Cancel</Button>
172	              <Button onClick={ingest} disabled={ingesting || (!ingestUrl && !ingestText)} className="gap-2">
