      description: `${kind.label} — ${narr.slice(0, 140)}`,
      tag: kind.label,
    };
  };

  const generateImageDirect = async (assetId: number, prompt: string) => {
    const base = import.meta.env.BASE_URL.replace(/\/$/, "");
